export function MinimalLoginScreen({ onSuccess, onDemo, onBack }: { onSuccess: (email: string, password: string) => void | Promise<void>; onDemo: () => void; onBack: () => void }) {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!email.trim() || password.length < 6) { notify('Enter an email and a password of at least 6 characters.'); return } setBusy(true); try { await onSuccess(email.trim(), password) } finally { setBusy(false) } }
  return <div className="prod-minimal-auth"><button className="prod-auth-back" onClick={onBack}><ArrowRight size={15} style={{ transform: 'rotate(180deg)' }} /> Back</button><form className="prod-minimal-card" onSubmit={submit}><div className="prod-auth-symbol"><Sparkles size={20} /></div><span className="eyebrow">Your study workspace</span><h1>Welcome back.</h1><p>Log in or create your focused workspace.</p><label>Email address<input autoFocus type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@example.com" /></label><label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 6 characters" /></label><button className="button primary auth-submit" type="submit" disabled={busy}>{busy ? 'Opening workspace…' : 'Continue'} {!busy && <ArrowRight size={16} />}</button><div className="minimal-or"><span>or</span></div><button className="button ghost auth-demo" type="button" onClick={onDemo}>Explore demo mode</button><small>Your progress is private to this account.</small></form></div>
}

export function FreshDashboard({ name, stats, onGenerate, onNavigate }: { name: string; stats: { questionsSolved: number; studyMinutes: number; accuracy: number; streak: number }; onGenerate: () => void; onNavigate: (page: WorkspacePage) => void }) {
  const hasActivity = stats.questionsSolved > 0 || stats.studyMinutes > 0
  return <div className="content fresh-dashboard"><div className="page-head"><div><div className="eyebrow">{hasActivity ? 'Your progress' : 'Your new workspace'}</div><h1>Hi {name} <span className="wave">✦</span></h1><p>{hasActivity ? 'Your saved activity is ready whenever you are.' : 'Your activity will appear here as you learn and practise.'}</p></div><button className="button primary" onClick={onGenerate}>Build your first test <ArrowRight size={16} /></button></div><section className="fresh-welcome"><div><span className="panel-kicker">{hasActivity ? 'Keep the rhythm going' : 'Start with a clean slate'}</span><h2>{hasActivity ? 'Pick up your preparation with a focused next session.' : 'Choose a chapter and make your first session count.'}</h2><p>Explore the full syllabus, save references, attempt a challenge or create a plan. Your workspace stays tied to {name}.</p><div className="fresh-actions"><button onClick={() => onNavigate('learn')}><BookOpen size={17} /> Browse syllabus</button><button onClick={() => onNavigate('practice')}><ListChecks size={17} /> Start practice</button><button onClick={() => onNavigate('plan')}><Target size={17} /> Make a plan</button></div></div><div className="fresh-orb"><Sparkles size={28} /></div></section><div className="fresh-zero-grid"><ZeroCard icon={<BookOpen />} label="Questions solved" value={stats.questionsSolved.toString()}/><ZeroCard icon={<Clock3 />} label="Study time" value={`${stats.studyMinutes} min`}/><ZeroCard icon={<Target />} label="Current accuracy" value={stats.accuracy ? `${stats.accuracy}%` : '—'}/><ZeroCard icon={<Zap />} label="Study streak" value={`${stats.streak} days`}/></div><section className="panel fresh-empty-panel"><div><h3>{hasActivity ? 'Your workspace is synced' : 'Your activity will build here'}</h3><p>{hasActivity ? 'Progress shown here is linked to your account and will be available when you log in again.' : `Once you complete a lesson or test, this space will show your real progress for ${name}.`}</p></div><button className="text-action" onClick={() => onNavigate('improve')}>Open analytics <ArrowRight size={14} /></button></section></div>
}
function ZeroCard({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="stat-card fresh-zero-card"><div className="stat-icon green">{icon}</div><span>{label}</span><strong>{value}</strong><small>Not enough activity yet</small></div> }

export function DashboardNextMove({ onNavigate }: { onNavigate: (page: WorkspacePage) => void }) {
  return <section className="panel dashboard-next-move"><div><span className="panel-kicker">Your next best move</span><h2>Repair Current Electricity before taking another full test.</h2><p>Do a 15-minute formula recall, solve 5 focused questions and review one mistake. Small, specific actions build a better score faster.</p><div className="dashboard-next-steps"><span><b>01</b> Recall Nernst + Ohm's law</span><span><b>02</b> Solve a 5-question sprint</span><span><b>03</b> Save the takeaway</span></div></div><div className="dashboard-next-actions"><button className="button primary" onClick={() => onNavigate('revision')}>Start revision <ArrowRight size={15} /></button><button className="text-action" onClick={() => onNavigate('analytics')}>See why this is next <BarChart3 size={14} /></button></div></section>
}

export function ReviewMistakesExperience({ name, demo, userKey, onBack, onTutor }: { name: string; demo: boolean; userKey: string; onBack: () => void; onTutor: () => void }) {
  const [items, setItems] = useState<StudyItem[]>([])
  const [expanded, setExpanded] = useState<string | null>(null)
  const [loading, setLoading] = useState(!demo)
  const localKey = `prepora-local-mistakes:${userKey.toLowerCase()}`
  useEffect(() => { const local = window.localStorage.getItem(localKey); if (local) { try { setItems(JSON.parse(local) as StudyItem[]) } catch { window.localStorage.removeItem(localKey) } } const token = window.localStorage.getItem('prepora-token'); if (!token) { setLoading(false); return } void loadStudyItems(token, 'mistake').then(next => { if (next?.length) setItems(current => [...next, ...current.filter(item => item.id.startsWith('local-'))]); setLoading(false) }) }, [localKey])
  const fallback: StudyItem[] = [
    { id: 'demo-mistake-1', kind: 'mistake', subject: 'Physics', class_level: '12th', chapter: 'Electric Charges and Fields', title: 'Electric field due to a uniformly charged shell', reason: 'Calculation error · revisit Gaussian surface and field region.', priority: 'High', duration_minutes: 15, status: 'open', due_date: null },
    { id: 'demo-mistake-2', kind: 'mistake', subject: 'Chemistry', class_level: '12th', chapter: 'Aldehydes, Ketones and Carboxylic Acids', title: 'Major product in aldol condensation', reason: 'Reaction recall · check alpha hydrogen and dehydration condition.', priority: 'High', duration_minutes: 15, status: 'open', due_date: null },
    { id: 'demo-mistake-3', kind: 'mistake', subject: 'Biology', class_level: '12th', chapter: 'Molecular Basis of Inheritance', title: 'Enzymes involved in DNA replication', reason: 'NCERT recall · compare leading and lagging strand processing.', priority: 'Medium', duration_minutes: 12, status: 'open', due_date: null },
  ]
  const visible = items.length ? items : (demo ? fallback : [])
  const complete = async (id: string) => { const token = window.localStorage.getItem('prepora-token'); if (token && !id.startsWith('demo-') && !id.startsWith('local-')) await completeStudyItem(token, id); setItems(current => { const next = current.filter(item => item.id !== id); window.localStorage.setItem(localKey, JSON.stringify(next.filter(item => item.id.startsWith('local-')))); return next }); setExpanded(current => current === id ? null : current) }
  const answerLabel = (item: StudyItem, answer: number | null | undefined) => answer === null || answer === undefined ? 'Not answered' : item.details?.options?.[answer] ?? `Option ${String.fromCharCode(65 + answer)}`
  return <div className="content fresh-improve"><div className="page-head"><div><div className="eyebrow">Improve · mistake notebook</div><h1>Review the questions you missed.</h1><p>Hi {name}. Fix the reasoning once, then retry the same concept with a fresh question.</p></div><button className="button ghost" onClick={onBack}><ArrowRight size={16} style={{ transform: 'rotate(180deg)' }} /> Back to Improve</button></div><section className="panel fresh-mistake-panel"><div className="section-title"><div><h2>Review mistakes</h2><span>{visible.length} open item{visible.length === 1 ? '' : 's'} from your latest test</span></div><button className="button primary" onClick={onTutor}><Sparkles size={15} /> Ask tutor</button></div>{loading ? <div className="fresh-empty-inline"><BookOpen size={21} /><div><strong>Loading your mistakes…</strong><p>Fetching the wrong answers saved to this account.</p></div></div> : visible.length ? visible.map(item => <article className="fresh-mistake-row" key={item.id}><div className={`fresh-mistake-icon ${item.subject.toLowerCase()}`}>{item.subject[0]}</div><div><strong>{item.title}</strong><span>{item.subject} · Class {item.class_level} · {item.chapter}</span><p>{item.reason}</p>{item.details?.questionText && <small className="mistake-preview">Question: {item.details.questionText}</small>}</div><div className="fresh-mistake-actions"><button className="button soft" onClick={() => setExpanded(current => current === item.id ? null : item.id)}>{expanded === item.id ? <ChevronDown size={14} /> : <BookOpen size={14} />} {expanded === item.id ? 'Hide answer' : 'View answer'}</button><button className="button soft" onClick={() => notify(`Retry set prepared for ${item.chapter}.`)}><RotateCcw size={14} /> Retry</button><button className="button soft" onClick={() => void complete(item.id)}><Check size={14} /> Reviewed</button></div>{expanded === item.id && <div className="mistake-detail"><div className="mistake-detail-label">Question</div><p className="mistake-question">{item.details?.questionText ?? `Question from ${item.chapter}`}</p>{item.details ? <><div className="mistake-detail-grid"><div><span>Your answer</span><strong>{answerLabel(item, item.details.selectedAnswer)}</strong></div><div><span>Correct answer</span><strong>{answerLabel(item, item.details.correctAnswer)}</strong></div></div><div className="mistake-explanation"><strong>Why</strong><p>{item.details.explanation}</p></div></> : <div className="mistake-explanation"><strong>Answer details</strong><p>This older mistake was saved before answer details were available. Retry the chapter to get a fresh explanation.</p></div>}</div>}</article>) : <div className="fresh-empty-inline"><Check size={21} /><div><strong>No mistakes saved yet.</strong><p>Complete another test and incorrect answers will appear here automatically.</p></div></div>}</section></div>
}

export function ReviewMistakesExperienceV2({ name, demo, userKey, onBack, onTutor }: { name: string; demo: boolean; userKey: string; onBack: () => void; onTutor: () => void }) {
  const [items, setItems] = useState<StudyItem[]>([])
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [loading, setLoading] = useState(!demo)
  const localKey = `prepora-local-mistakes:${userKey.toLowerCase()}`
  const fallback: StudyItem[] = [
    { id: 'demo-mistake-1', kind: 'mistake', subject: 'Physics', class_level: '12th', chapter: 'Electric Charges and Fields', title: 'Electric field due to a uniformly charged shell', reason: 'Calculation error · revisit Gaussian surface and field region.', priority: 'High', duration_minutes: 15, status: 'open', due_date: null, details: { questionText: 'If both point charges are doubled while distance remains the same, the electrostatic force becomes:', options: ['Half', 'Double', 'Four times', 'Unchanged'], selectedAnswer: 1, correctAnswer: 2, explanation: 'Coulomb force is proportional to q₁q₂. Doubling both charges makes the force four times.' } },
    { id: 'demo-mistake-2', kind: 'mistake', subject: 'Chemistry', class_level: '12th', chapter: 'Aldehydes, Ketones and Carboxylic Acids', title: 'Major product in aldol condensation', reason: 'Reaction recall · check alpha hydrogen and dehydration condition.', priority: 'High', duration_minutes: 15, status: 'open', due_date: null, details: { questionText: 'Which check should come first when predicting the major product in an aldol condensation?', options: ['Identify alpha hydrogen and reaction conditions', 'Choose the longest option', 'Ignore dehydration conditions', 'Count only oxygen atoms'], selectedAnswer: 2, correctAnswer: 0, explanation: 'First identify the alpha hydrogen and conditions; these determine whether aldol addition or dehydration is favoured.' } },
    { id: 'demo-mistake-3', kind: 'mistake', subject: 'Biology', class_level: '12th', chapter: 'Molecular Basis of Inheritance', title: 'Enzymes involved in DNA replication', reason: 'NCERT recall · compare leading and lagging strand processing.', priority: 'Medium', duration_minutes: 12, status: 'open', due_date: null, details: { questionText: 'The enzyme that joins Okazaki fragments is:', options: ['DNA polymerase', 'DNA ligase', 'Helicase', 'Primase'], selectedAnswer: 0, correctAnswer: 1, explanation: 'DNA ligase seals the nicks between Okazaki fragments on the lagging strand.' } },
  ]
  useEffect(() => { const local = window.localStorage.getItem(localKey); if (local) { try { setItems(JSON.parse(local) as StudyItem[]) } catch { window.localStorage.removeItem(localKey) } } const token = window.localStorage.getItem('prepora-token'); if (!token) { setLoading(false); return } void loadStudyItems(token, 'mistake').then(next => { if (next?.length) setItems(current => [...next, ...current.filter(item => item.id.startsWith('local-'))]); setLoading(false) }) }, [localKey])
  const visible = items.length ? items : (demo ? fallback : [])
  useEffect(() => { if (!visible.length) { setSelectedId(null); return } if (!selectedId || !visible.some(item => item.id === selectedId)) setSelectedId(visible[0].id) }, [visible, selectedId])
  const selected = visible.find(item => item.id === selectedId) ?? visible[0]
  const complete = async (id: string) => { const token = window.localStorage.getItem('prepora-token'); if (token && !id.startsWith('demo-') && !id.startsWith('local-')) await completeStudyItem(token, id); const next = visible.filter(item => item.id !== id); setItems(current => current.filter(item => item.id !== id)); window.localStorage.setItem(localKey, JSON.stringify(next.filter(item => item.id.startsWith('local-')))); setSelectedId(next[0]?.id ?? null); notify('Marked as reviewed. Keep the takeaway in your next revision session.') }
  const answerLabel = (item: StudyItem, answer: number | null | undefined) => answer === null || answer === undefined ? 'Not answered' : item.details?.options?.[answer] ?? `Option ${String.fromCharCode(65 + answer)}`
  const details = selected?.details
  return <div className="content fresh-improve review-workspace"><div className="page-head"><div><div className="eyebrow">Improve · test review</div><h1>Understand every missed question.</h1><p>Hi {name}. Review the reasoning, capture the takeaway and then retry the concept.</p></div><div className="review-header-actions"><button className="button ghost" onClick={onBack}><ArrowRight size={16} style={{ transform: 'rotate(180deg)' }} /> Back to Improve</button><button className="button primary" onClick={onTutor}><Sparkles size={15} /> Ask tutor</button></div></div>{loading ? <section className="panel review-loading"><BookOpen size={22} /><strong>Loading your test review…</strong><span>Fetching the questions and answers from your saved mistakes.</span></section> : !selected ? <section className="panel review-empty"><Check size={26} /><h2>No mistakes to review</h2><p>Complete a test and your incorrect or unanswered questions will appear here.</p><button className="button primary" onClick={onBack}>Back to Improve</button></section> : <><div className="review-summary"><div><span className="panel-kicker">Open mistake review</span><strong>{visible.length} question{visible.length === 1 ? '' : 's'} need attention</strong><small>Start with the first one and work through the list.</small></div><div className="review-summary-stats"><div><b>{visible.filter(item => item.details?.selectedAnswer !== null && item.details?.selectedAnswer !== undefined).length}</b><span>answered wrong</span></div><div><b>{visible.filter(item => item.details?.selectedAnswer === null || item.details?.selectedAnswer === undefined).length}</b><span>unanswered</span></div></div></div><div className="review-shell"><aside className="panel review-question-list"><div className="review-list-head"><div><strong>Questions to review</strong><span>{visible.length} open items</span></div><span className="count-chip">{visible.length}</span></div>{visible.map((item, index) => <button key={item.id} className={item.id === selected.id ? 'review-list-item active' : 'review-list-item'} onClick={() => setSelectedId(item.id)}><span className={`review-list-number ${item.details?.selectedAnswer === null || item.details?.selectedAnswer === undefined ? 'unanswered' : 'wrong'}`}>{index + 1}</span><span className="review-list-copy"><strong>{item.chapter}</strong><small>{item.subject} · {item.details?.selectedAnswer === null || item.details?.selectedAnswer === undefined ? 'Unanswered' : 'Incorrect'}</small></span><ChevronRight size={15} /></button>)}</aside><section className="panel review-detail"><div className="review-detail-head"><div><span className="panel-kicker">Question {String(visible.findIndex(item => item.id === selected.id) + 1).padStart(2, '0')} · {selected.subject}</span><h2>{selected.chapter}</h2><span className="review-mistake-tag">{selected.details?.selectedAnswer === null || selected.details?.selectedAnswer === undefined ? 'Unanswered' : 'Incorrect answer'}</span></div><span className="review-points">+4 / −1</span></div><div className="review-question-block"><span>Question</span><h3>{details?.questionText ?? `Review the key concept from ${selected.chapter}.`}</h3></div>{details ? <><div className="review-options">{details.options.map((option, index) => <div key={`${selected.id}-${option}`} className={index === details.correctAnswer ? 'review-option correct' : index === details.selectedAnswer ? 'review-option wrong' : 'review-option'}><span>{String.fromCharCode(65 + index)}</span><strong>{option}</strong>{index === details.correctAnswer && <small>Correct answer</small>}{index === details.selectedAnswer && index !== details.correctAnswer && <small>Your answer</small>}</div>)}</div><div className="review-answer-grid"><div className="your-answer"><span>Your answer</span><strong>{answerLabel(selected, details.selectedAnswer)}</strong></div><div className="correct-answer"><span>Correct answer</span><strong>{answerLabel(selected, details.correctAnswer)}</strong></div></div><div className="review-explanation"><div className="review-explanation-icon"><Lightbulb size={17} /></div><div><span>Explanation</span><p>{details.explanation}</p></div></div></> : <div className="review-no-details"><BookOpen size={18} /><div><strong>Detailed answer not available for this older item.</strong><p>Retry this chapter to save the full question, answer and explanation.</p></div></div>}<div className="review-detail-actions"><button className="button primary" onClick={() => notify(`Retry set prepared for ${selected.chapter}.`)}><RotateCcw size={15} /> Retry this concept</button><button className="button soft" onClick={() => void complete(selected.id)}><Check size={15} /> Mark reviewed</button></div></section></div></>}</div>
}

export function WorkspaceOverlay({ kind, name, email, onClose, onNavigate, onSignOut }: { kind: 'search' | 'settings' | 'profile'; name: string; email: string; onClose: () => void; onNavigate: (page: WorkspacePage) => void; onSignOut: () => void }) {
  const [query, setQuery] = useState('')
  const [goal, setGoal] = useState('NEET-UG')
  const [results, setResults] = useState<{ label: string; page: WorkspacePage; icon: React.ReactNode }[]>([{ label: 'Formula & reaction bank', page: 'learn', icon: <BookOpen size={16} /> }, { label: 'Practice challenge', page: 'practice', icon: <ListChecks size={16} /> }, { label: 'Mistake notebook', page: 'improve', icon: <BarChart3 size={16} /> }])
  useEffect(() => { let active = true; const base = [{ label: 'Formula & reaction bank', page: 'learn' as WorkspacePage, icon: <BookOpen size={16} /> }, { label: 'Practice challenge', page: 'practice' as WorkspacePage, icon: <ListChecks size={16} /> }, { label: 'Mistake notebook', page: 'improve' as WorkspacePage, icon: <BarChart3 size={16} /> }].filter(item => item.label.toLowerCase().includes(query.toLowerCase())); if (!query.trim()) { setResults(base); return () => { active = false } }; void searchContent(query).then(items => { if (!active) return; setResults(items?.slice(0, 8).map(item => ({ label: item.title, page: 'learn' as WorkspacePage, icon: item.subject === 'Physics' ? <Zap size={16} /> : item.subject === 'Chemistry' ? <FlaskConical size={16} /> : <BookOpen size={16} /> })) ?? base) }); return () => { active = false } }, [query, kind])
  const saveSettings = async () => { const token = window.localStorage.getItem('prepora-token'); if (token) await updateProfile(token, { target_exam: goal }); notify('Settings saved for this profile.'); onClose() }
  return <div className="workspace-overlay-backdrop" onClick={onClose}><section className="workspace-overlay" onClick={e => e.stopPropagation()}><button className="workspace-close" onClick={onClose}><X size={17} /></button>{kind === 'search' && <><div className="overlay-kicker"><Search size={15} /> Search workspace</div><h2>Find a study tool</h2><input className="overlay-search" autoFocus value={query} onChange={e => setQuery(e.target.value)} placeholder="Search formulas, reactions, chapters..." /> <div className="overlay-results">{results.map(item => <button key={item.label} onClick={() => { onNavigate(item.page); onClose() }}>{item.icon}<span>{item.label}</span><ArrowRight size={14} /></button>)}{results.length === 0 && <p>No matching content found.</p>}</div></>}{kind === 'settings' && <><div className="overlay-kicker"><Settings size={15} /> Settings</div><h2>Workspace preferences</h2><p className="overlay-copy">These preferences belong to {name}.</p><label>Target exam<select value={goal} onChange={e => setGoal(e.target.value)}><option>NEET-UG</option><option>CBSE Boards</option><option>CUET-UG</option><option>AIIMS Nursing</option></select></label><label>Default scope<select><option>Mixed · Class 11 + 12</option><option>Class 11</option><option>Class 12</option></select></label><button className="button primary overlay-save" onClick={() => void saveSettings()}><Check size={15} /> Save preferences</button></>}{kind === 'profile' && <><div className="overlay-profile-avatar"><UserRound size={22} /></div><div className="overlay-kicker">Profile</div><h2>{name}</h2><p className="overlay-copy">{email}</p><div className="profile-stat"><span>Account identity</span><strong>Private workspace profile</strong></div><button className="button ghost overlay-save" onClick={onSignOut}><LogOut size={15} /> Log out</button></>}</section></div>
}

export function FreshImprove({ name, onTutor }: { name: string; onTutor: () => void }) {
  const [snapshot, setSnapshot] = useState<AnalyticsSnapshot | null>(null)
  const [mistakes, setMistakes] = useState<StudyItem[]>([])
  useEffect(() => { const token = window.localStorage.getItem('prepora-token'); if (token) { void loadAnalytics(token).then(setSnapshot); void loadStudyItems(token, 'mistake').then(items => items && setMistakes(items)) } }, [])
  const complete = async (id: string) => { const token = window.localStorage.getItem('prepora-token'); if (!token) return; await completeStudyItem(token, id); setMistakes(items => items.filter(item => item.id !== id)); void loadAnalytics(token).then(setSnapshot) }
  const hasEvidence = Boolean(snapshot?.attempt_count)
  return <div className="content fresh-improve"><div className="page-head"><div><div className="eyebrow">Improve · evidence into action</div><h1>See the pattern, then change it.</h1><p>Hi {name}. Your analytics, recommendations and mistakes stay linked to your account.</p></div><button className="button primary" onClick={onTutor}><Sparkles size={16} /> Ask the tutor</button></div><div className="fresh-analytics-grid"><section className="panel fresh-analytics-main"><div className="panel-kicker">{hasEvidence ? 'Evidence from your attempts' : 'Ready for your first evidence'}</div><h2>{hasEvidence ? `${snapshot?.average_score}% average score` : 'No performance data yet'}</h2><p>{hasEvidence ? `Best score ${snapshot?.best_score}% across ${snapshot?.attempt_count} saved attempt${snapshot?.attempt_count === 1 ? '' : 's'}.` : 'Complete a timed test to unlock accuracy, score trend and targeted recommendations.'}</p><div className="fresh-subject-bars">{['Physics', 'Chemistry', 'Biology'].map(subject => <div key={subject}><span>{subject}</span><div><i style={{ width: `${snapshot?.subject_accuracy?.[subject] ?? 0}%` }} /></div><b>{snapshot?.subject_accuracy?.[subject] ? `${snapshot.subject_accuracy[subject]}%` : '—'}</b></div>)}</div><div className="fresh-recommendation"><Target size={17} /><span>{snapshot?.recommendation ?? 'Start with a chapter reference, then attempt the focused test to create a useful baseline.'}</span></div></section><section className="panel fresh-analytics-side"><span className="panel-kicker">Next best move</span><strong>{mistakes.length || snapshot?.open_items || 0}</strong><p>open review items</p><button className="text-action" onClick={onTutor}>Discuss the weak spot <ArrowRight size={14} /></button></section></div><section className="panel fresh-mistake-panel"><div className="section-title"><div><h2>Mistake notebook</h2><span>Every incorrect answer can become a focused revision task.</span></div><span className="count-chip">{mistakes.length} open</span></div>{mistakes.length ? mistakes.map(item => <article className="fresh-mistake-row" key={item.id}><div className={`fresh-mistake-icon ${item.subject.toLowerCase()}`}>{item.subject[0]}</div><div><strong>{item.title}</strong><span>{item.subject} · {item.chapter} · {item.duration_minutes} min</span><p>{item.reason}</p></div><button className="button soft" onClick={() => void complete(item.id)}><Check size={14} /> Mark reviewed</button></article>) : <div className="fresh-empty-inline"><BookOpen size={21} /><div><strong>Your notebook is clear.</strong><p>Start a test to let real mistakes populate this space.</p></div></div>}</section></div>
}

export function FreshPlan({ name, onLearn }: { name: string; onLearn: () => void }) {
  const [tab, setTab] = useState<'queue' | 'planner'>('queue')
  const [items, setItems] = useState<StudyItem[]>([])
  const [busy, setBusy] = useState(false)
  useEffect(() => { const token = window.localStorage.getItem('prepora-token'); if (token) void loadStudyItems(token).then(next => next && setItems(next)) }, [])
  const complete = async (id: string) => { const token = window.localStorage.getItem('prepora-token'); if (!token) return; await completeStudyItem(token, id); setItems(current => current.map(item => item.id === id ? { ...item, status: 'completed' } : item)) }
  const addStarter = async () => { const token = window.localStorage.getItem('prepora-token'); if (!token) return; setBusy(true); const created = await createStudyItem(token, { kind: 'planner', subject: 'Biology', class_level: '12th', chapter: 'Molecular Basis of Inheritance', title: 'NCERT recall · Molecular Basis of Inheritance', reason: 'A 20-minute starter session across DNA replication, transcription and translation.', priority: 'High', duration_minutes: 20 }); if (created?.item) setItems(current => [created.item, ...current]); setBusy(false) }
  const visible = items.filter(item => item.status === 'open' && (tab === 'queue' ? item.kind !== 'planner' : item.kind === 'planner'))
  return <div className="content fresh-plan"><div className="page-head"><div><div className="eyebrow">Plan · your next useful session</div><h1>Make the next step obvious.</h1><p>Hi {name}. Your queue is built from your real attempts, saved mistakes and chosen study sessions.</p></div><button className="button primary" onClick={onLearn}>Browse syllabus <BookOpen size={16} /></button></div><div className="area-tabs prod-tabs"><button className={tab === 'queue' ? 'active' : ''} onClick={() => setTab('queue')}>Smart queue</button><button className={tab === 'planner' ? 'active' : ''} onClick={() => setTab('planner')}>Study planner</button></div><section className="panel fresh-plan-panel"><div className="section-title"><div><h2>{tab === 'queue' ? 'Smart Revision Queue' : 'Study Planner'}</h2><span>{visible.length} open session{visible.length === 1 ? '' : 's'} · prioritised from your workspace data</span></div><button className="button soft" onClick={() => void addStarter()} disabled={busy}>{busy ? 'Adding…' : 'Add starter session'}</button></div>{visible.length ? visible.map(item => <article className="fresh-plan-row" key={item.id}><div className={`fresh-plan-icon ${item.subject.toLowerCase()}`}>{item.subject === 'Physics' ? <Zap size={17} /> : item.subject === 'Chemistry' ? <FlaskConical size={17} /> : <Leaf size={17} />}</div><div><strong>{item.title}</strong><span>{item.subject} · Class {item.class_level} · {item.duration_minutes} min</span><p>{item.reason}</p></div><b className={item.priority === 'High' ? 'fresh-priority-high' : ''}>{item.priority}</b><button className="button soft" onClick={() => void complete(item.id)}><Check size={14} /> Done</button></article>) : <div className="fresh-empty-inline"><Target size={22} /><div><strong>Your {tab === 'queue' ? 'revision queue' : 'planner'} is clear.</strong><p>Complete a test to generate review work, or add a starter session to begin with real syllabus content.</p><button className="text-action" onClick={onLearn}>Choose a chapter <ArrowRight size={14} /></button></div></div>}</section><div className="fresh-plan-content"><span className="panel-kicker">Content in every session</span><strong>Recall → practise → review → schedule</strong><span>Physics formulas, Chemistry reaction conditions and Biology NCERT anchors are available chapter by chapter in Learn.</span></div></div>
}

export function TutorExperienceAdvanced() {
  const [mode, setMode] = useState<'Explain simply' | 'Step-by-step' | 'Quiz me' | 'Revision plan'>('Explain simply')
  const [input, setInput] = useState('')
  const [pending, setPending] = useState(false)
  const [messages, setMessages] = useState<{ role: 'tutor' | 'student'; text: string }[]>([{ role: 'tutor', text: 'Welcome back. Tell me the chapter, formula, reaction or mistake you want to work on.' }])
  const localReply = (prompt: string, selectedMode = mode) => { const lower = prompt.toLowerCase(); if (selectedMode === 'Quiz me') return 'Quick check: what happens to electric field when distance from a point charge doubles? Reply with the factor and your reasoning.'; if (selectedMode === 'Revision plan') return '15-minute plan: 4 min active recall, 6 min solve two questions, 3 min review one mistake, 2 min write the takeaway.'; if (lower.includes('potential') || lower.includes('electro')) return 'Electric potential is work done per unit positive test charge. For a point charge, V = kq/r. Check the sign of q and the distance before substituting.'; if (lower.includes('aldol') || lower.includes('amine')) return 'First identify the functional group and reaction condition. Write reactant → reagent/condition → product, then check carbon count and side reactions.'; return 'Let’s make it exam-ready: name the concept, write the governing relation, check units or conditions, then explain why the option follows.' }
  const send = async (text = input, selectedMode = mode) => { const prompt = text.trim() || `Switching to ${selectedMode} mode`; setMessages(current => [...current, { role: 'student', text: prompt }]); setInput(''); setPending(true); const token = window.localStorage.getItem('prepora-token'); const remote = token ? await askTutor(token, prompt, selectedMode) : null; setMessages(current => [...current, { role: 'tutor', text: remote?.reply ?? localReply(prompt, selectedMode) }]); setPending(false) }
  return <div className="content"><div className="page-head"><div><div className="eyebrow">Study tutor · chapter-aware coaching</div><h1>Ask better questions.</h1><p>Get a focused explanation, a recall check or a revision plan using your current study context.</p></div><span className="prod-local-chip">{pending ? 'Thinking…' : 'Ready'}</span></div><div className="prod-tutor-layout"><section className="panel prod-chat"><div className="prod-chat-head"><div className="tutor-avatar"><Sparkles size={17} /></div><div><strong>PrePora study tutor</strong><span>Physics · Chemistry · Biology · Class 11 + 12</span></div><span className="prod-local-chip">Context-aware</span></div><div className="prod-mode-row">{(['Explain simply', 'Step-by-step', 'Quiz me', 'Revision plan'] as const).map(item => <button className={mode === item ? 'active' : ''} key={item} onClick={() => { setMode(item); void send('', item) }}>{item}</button>)}</div><div className="prod-chat-messages">{messages.map((message, i) => <div className={message.role === 'tutor' ? 'prod-message tutor' : 'prod-message student'} key={`${message.text}-${i}`}><span>{message.role === 'tutor' ? <Sparkles size={14} /> : 'AS'}</span><p>{message.text}</p></div>)}</div><div className="prod-chat-compose"><input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && void send()} placeholder="Ask about a formula, reaction, diagram or mistake..." /><button className="button primary" onClick={() => void send()} disabled={pending}><ArrowRight size={17} /></button></div><small className="ai-note">Provider-backed responses are used when the API is available; otherwise the local coaching fallback stays honest and usable.</small></section><aside className="prod-tutor-side"><div className="panel prod-tutor-context"><h3>Try a focused prompt</h3>{['Explain electric potential simply', 'Quiz me on Molecular Basis of Inheritance', 'Make a 15-minute Chemistry revision plan', 'Show the steps for a current electricity numerical'].map(prompt => <button key={prompt} onClick={() => void send(prompt)}>{prompt}<ArrowRight size={14} /></button>)}</div><div className="panel prod-tutor-context"><h3>Better answers start with context</h3><span><Check size={14} /> Name the chapter</span><span><Check size={14} /> Share what you tried</span><span><Check size={14} /> Ask for a practice check</span></div></aside></div></div>
}

export function TestCenterExperience({ onBuildTest, onStartExam }: { onBuildTest: () => void; onStartExam: () => void }) { const modes = [{ title: 'Full NEET mock', meta: '180 questions · 180 min', text: 'A complete exam simulation with subject balance and negative marking.', tone: 'physics' }, { title: 'Subject sprint', meta: '45 questions · 45 min', text: 'Build speed and accuracy in one focused Physics, Chemistry or Biology session.', tone: 'chemistry' }, { title: 'Chapter test', meta: '15–60 questions', text: 'Stay inside one chapter and see exactly where the concept breaks.', tone: 'biology' }]; return <div className="content extra-page"><div className="page-head"><div><div className="eyebrow">Tests · exam practice</div><h1>Choose the test that fits today.</h1><p>Use a full mock for stamina, a sprint for speed or a chapter test for repair.</p></div><button className="button primary" onClick={onBuildTest}><Plus size={16} /> Build custom test</button></div><section className="extra-hero"><div><span className="panel-kicker">Recommended next step</span><h2>Start a 30-question mixed sprint.</h2><p>Balanced Physics, Chemistry and Biology practice with a live timer.</p><button className="button primary" onClick={onStartExam}>Start recommended test <ArrowRight size={15} /></button></div><div className="extra-hero-stat"><strong>78%</strong><span>last test accuracy</span><small>+6% this week</small></div></section><div className="extra-card-grid">{modes.map(mode => <article className={`panel extra-mode-card ${mode.tone}`} key={mode.title}><div className="extra-card-icon"><FileText size={19} /></div><span className="panel-kicker">{mode.meta}</span><h3>{mode.title}</h3><p>{mode.text}</p><button className="text-action" onClick={onBuildTest}>Set up this test <ArrowRight size={14} /></button></article>)}</div><section className="panel extra-history"><div className="section-title"><div><h2>Recent attempts</h2><span>Use your last attempt as evidence, not judgement.</span></div><button className="text-action">View all <ArrowRight size={14} /></button></div>{['Mixed sprint · 78% · Today', 'Physics chapter test · 64% · Yesterday', 'Biology NCERT recall · 86% · 3 days ago'].map(item => <div className="extra-history-row" key={item}><span className="history-dot" /><strong>{item.split(' · ')[0]}</strong><span>{item.split(' · ').slice(1).join(' · ')}</span><ChevronRight size={15} /></div>)}</section></div> }

export function TestHistory({ userKey }: { userKey: string }) {
  const [attempts, setAttempts] = useState<TestAttempt[]>([])
  useEffect(() => {
    const localKey = `prepora-local-attempts:${userKey.toLowerCase()}`
    let local: TestAttempt[] = []
    try { local = JSON.parse(window.localStorage.getItem(localKey) ?? '[]') as TestAttempt[] } catch { local = [] }
    const token = window.localStorage.getItem('prepora-token')
    if (!token) { setAttempts(local); return }
    void loadTestAttempts(token).then(remote => setAttempts([...(remote ?? []), ...local]))
  }, [userKey])
  const label = (attempt: TestAttempt) => { const config = attempt.config ?? {}; const exam = config.exam ?? 'Exam'; const subject = config.subject ?? 'Mixed'; const chapter = config.chapter && config.chapter !== 'Full syllabus' ? ` · ${config.chapter}` : ''; const count = config.questions ? ` · ${config.questions} Q` : ''; return `${exam} · ${subject}${chapter}${count}` }
  return <section className="panel extra-history test-history"><div className="section-title"><div><h2>Test history</h2><span>{attempts.length ? `${attempts.length} saved attempt${attempts.length === 1 ? '' : 's'}` : 'Your completed tests will appear here.'}</span></div><Clock3 size={18} color="#8ca09a" /></div>{attempts.length ? attempts.slice(0, 20).map(attempt => <div className="extra-history-row" key={attempt.id}><span className="history-dot" /><div><strong>{label(attempt)}</strong><small>{new Date(attempt.created_at).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })}</small></div><span className="history-result">{Math.round(attempt.score)}% · {attempt.correct} correct · {attempt.incorrect} wrong</span><ChevronRight size={15} /></div>) : <div className="fresh-empty-inline"><FileText size={21} /><div><strong>No completed tests yet.</strong><p>Create a test, submit it and this list will remember the test scope, date and result.</p></div></div>}</section>
}

export function PYQExperience() { const [subject, setSubject] = useState('All subjects'); const [year, setYear] = useState('All years'); const papers = [{ subject: 'Physics', year: 'NEET 2025', title: 'Electrostatics and Current Electricity', count: '45 questions', difficulty: 'Mixed' }, { subject: 'Chemistry', year: 'NEET 2024', title: 'Physical Chemistry essentials', count: '45 questions', difficulty: 'Medium' }, { subject: 'Biology', year: 'NEET 2023', title: 'Genetics and Human Health', count: '90 questions', difficulty: 'NCERT-first' }, { subject: 'Mixed', year: 'NEET 2022', title: 'Complete PCB paper', count: '200 questions', difficulty: 'Full paper' }]; const visible = papers.filter(item => (subject === 'All subjects' || item.subject === subject || item.subject === 'Mixed') && (year === 'All years' || item.year === year)); return <div className="content extra-page"><div className="page-head"><div><div className="eyebrow">PYQs · learn the pattern</div><h1>Practise what the exam has already asked.</h1><p>Filter by subject and year, then review the concept behind every repeated pattern.</p></div><span className="prod-local-chip">1990–2025 archive</span></div><div className="extra-controls"><label>Subject<select value={subject} onChange={e => setSubject(e.target.value)}><option>All subjects</option><option>Physics</option><option>Chemistry</option><option>Biology</option></select></label><label>Year<select value={year} onChange={e => setYear(e.target.value)}><option>All years</option><option>NEET 2025</option><option>NEET 2024</option><option>NEET 2023</option><option>NEET 2022</option></select></label><div className="extra-control-note"><Target size={16} /> Prioritise repeated concepts before chasing new questions.</div></div><div className="extra-card-grid pyq-grid">{visible.map(item => <article className="panel extra-pyq-card" key={`${item.subject}-${item.year}`}><div className="extra-pyq-top"><span className={`subject-label ${item.subject.toLowerCase()}`}>{item.subject}</span><b>{item.year}</b></div><h3>{item.title}</h3><p>{item.count} · {item.difficulty}</p><div className="pyq-progress"><span style={{ width: item.subject === 'Biology' ? '72%' : item.subject === 'Physics' ? '48%' : '31%' }} /></div><div className="extra-card-actions"><button className="button soft" onClick={() => notify(`Opened ${item.title}.`)}>View questions</button><button className="text-action" onClick={() => notify('PYQ explanation mode is ready for this set.')}>Study pattern <ArrowRight size={14} /></button></div></article>)}</div></div> }

export function RevisionHubExperience() { const [done, setDone] = useState<string[]>([]); const cards = [{ id: 'physics', subject: 'Physics', title: 'Electric Charges and Fields', kind: 'Formula recall', due: 'Due today', text: 'Coulomb law, electric field and Gaussian surface.' }, { id: 'chemistry', subject: 'Chemistry', title: 'Electrochemistry', kind: 'Reaction + formula', due: 'Due today', text: 'Cell potential, Nernst equation and conductivity.' }, { id: 'biology', subject: 'Biology', title: 'Molecular Basis of Inheritance', kind: 'NCERT recall', due: 'Due tomorrow', text: 'Replication, transcription and translation.' }]; return <div className="content extra-page"><div className="page-head"><div><div className="eyebrow">Revision · remember at the right time</div><h1>Small recall sessions that stay with you.</h1><p>Review the anchor, retrieve it without notes and then solve one application question.</p></div><span className="prod-local-chip">{cards.length - done.length} due today</span></div><section className="revision-flow"><div className="revision-flow-step"><b>01</b><strong>Recall</strong><span>Close the notes.</span></div><div className="revision-flow-step"><b>02</b><strong>Check</strong><span>Compare the anchor.</span></div><div className="revision-flow-step"><b>03</b><strong>Apply</strong><span>Solve one question.</span></div></section><div className="revision-grid">{cards.map(card => <article className={done.includes(card.id) ? 'panel revision-card completed' : 'panel revision-card'} key={card.id}><div className={`extra-card-icon ${card.subject.toLowerCase()}`}><BookOpen size={18} /></div><div className="revision-card-top"><span>{card.subject} · {card.kind}</span><b>{card.due}</b></div><h3>{card.title}</h3><p>{card.text}</p><div className="revision-card-actions"><button className="button soft" onClick={() => { setDone(current => current.includes(card.id) ? current.filter(id => id !== card.id) : [...current, card.id]); notify(done.includes(card.id) ? 'Revision item reopened.' : 'Revision item marked complete.') }}>{done.includes(card.id) ? <RotateCcw size={14} /> : <Check size={14} />} {done.includes(card.id) ? 'Review again' : 'Mark complete'}</button><button className="text-action" onClick={() => notify(`Opening ${card.title} recall card.`)}>Open card <ArrowRight size={14} /></button></div></article>)}</div></div> }

export function AnalyticsExperience() { const subjects = [{ name: 'Physics', accuracy: 71, solved: 218, tone: 'physics' }, { name: 'Chemistry', accuracy: 82, solved: 201, tone: 'chemistry' }, { name: 'Biology', accuracy: 84, solved: 223, tone: 'biology' }]; return <div className="content extra-page"><div className="page-head"><div><div className="eyebrow">Analytics · evidence over guesses</div><h1>See what is changing your score.</h1><p>Accuracy is only one signal. Watch speed, consistency and chapter-level gaps together.</p></div><span className="prod-local-chip">Last 30 days</span></div><div className="analytics-kpis extra-kpis"><div><span>Average score</span><strong>78%</strong><small>+6.2% vs previous period</small></div><div><span>Questions solved</span><strong>642</strong><small>18 this week</small></div><div><span>Avg. time/question</span><strong>54s</strong><small>8s faster this week</small></div><div><span>Revision consistency</span><strong>76%</strong><small>12-day streak</small></div></div><div className="analytics-extra-grid"><section className="panel"><div className="section-title"><div><h2>Subject accuracy</h2><span>Where your effort is converting into marks.</span></div></div><div className="analytics-subject-list">{subjects.map(item => <div className="analytics-subject-row" key={item.name}><span className={`analytics-subject-icon ${item.tone}`}>{item.name[0]}</span><div><strong>{item.name}</strong><small>{item.solved} questions solved</small></div><div className="analytics-bar"><i style={{ width: `${item.accuracy}%` }} /></div><b>{item.accuracy}%</b></div>)}</div></section><section className="panel analytics-next"><span className="panel-kicker">Next best move</span><h2>Repair Physics speed.</h2><p>Your accuracy is stable, but Current Electricity takes 12 seconds longer than your average.</p><button className="button primary" onClick={() => notify('A Physics speed set was added to your plan.')}>Start a speed set <ArrowRight size={15} /></button></section></div><section className="panel analytics-heatmap"><div className="section-title"><div><h2>Chapter health</h2><span>Green is ready, amber needs a short revision, red needs attention.</span></div></div><div className="health-grid">{['Electrostatics', 'Current Electricity', 'Ray Optics', 'Electrochemistry', 'Genetics', 'Human Health', 'Thermodynamics', 'Coordination Compounds', 'Ecology'].map((item, index) => <div className={`health-cell health-${index % 3}`} key={item}><strong>{item}</strong><span>{index % 3 === 0 ? 'Needs work' : index % 3 === 1 ? 'Building' : 'Ready'}</span></div>)}</div></section></div> }

export function LibraryExperience() { const [tab, setTab] = useState<'saved' | 'notes' | 'sets'>('saved'); const items = { saved: ['Lens formula using Cartesian sign convention', 'DNA replication: Okazaki fragments', 'Nernst equation quick reference'], notes: ['Current Electricity · common sign traps', 'Amines · named reactions to revisit', 'Genetics · NCERT one-line recall'], sets: ['Physics speed repair · 15 questions', 'Biology NCERT recall · 30 questions', 'Mixed mistakes · latest test'] }; return <div className="content extra-page"><div className="page-head"><div><div className="eyebrow">My Library · your study shelf</div><h1>Keep the things worth revisiting.</h1><p>Saved questions, personal notes and custom sets stay together instead of disappearing after one session.</p></div><button className="button primary" onClick={() => notify('Create a custom set from your saved questions.')}> <Plus size={16} /> Create set</button></div><div className="library-stats"><div><strong>12</strong><span>saved questions</span></div><div><strong>8</strong><span>personal notes</span></div><div><strong>3</strong><span>custom sets</span></div></div><div className="area-tabs prod-tabs library-tabs">{(['saved', 'notes', 'sets'] as const).map(item => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item === 'saved' ? 'Saved questions' : item === 'notes' ? 'My notes' : 'Custom sets'}</button>)}</div><section className="panel library-list"><div className="section-title"><div><h2>{tab === 'saved' ? 'Saved questions' : tab === 'notes' ? 'Personal notes' : 'Custom sets'}</h2><span>{items[tab].length} items ready for your next session.</span></div><Search size={18} color="#8ca09a" /></div>{items[tab].map((item, index) => <div className="library-row" key={item}><span className={`library-row-number library-${index % 3}`}>{String(index + 1).padStart(2, '0')}</span><div><strong>{item}</strong><small>{tab === 'saved' ? 'Physics · saved from Learn' : tab === 'notes' ? 'Updated this week' : 'Ready to practise'}</small></div><button className="text-action" onClick={() => notify(`Opening ${item}.`)}>Open <ArrowRight size={14} /></button></div>)}</section></div> }

export function PhotoWorkspaceAdvanced({ photo, onPhoto, onRemove }: { photo: { file: File; url: string } | null; onPhoto: (file: File | undefined) => void; onRemove: () => void }) {
  const [questionText, setQuestionText] = useState('')
  const [analysis, setAnalysis] = useState<{ reply: string; notice: string } | null>(null)
  const [busy, setBusy] = useState(false)
  const runAnalysis = async () => { if (!photo) return; setBusy(true); const token = window.localStorage.getItem('prepora-token'); const remote = token ? await analyzePhoto(token, photo.file, questionText) : null; setAnalysis(remote ?? { reply: questionText ? 'Question context received. Start by identifying the concept, write the governing relation and check the given conditions before solving.' : 'Image preview is ready. Add the exact question text for a reliable step-by-step explanation.', notice: 'Local fallback is active; configure the API and vision provider for OCR.' }); setBusy(false) }
  return <section className="panel prod-photo"><div className="prod-photo-hero"><div className="prod-photo-icon"><ImagePlus size={24} /></div><div><span className="panel-kicker">Ask from photo · guided workflow</span><h2>Upload, add context, get a solution path.</h2><p>PrePora validates the image first, then uses your typed context and study content without pretending OCR worked when it did not.</p></div></div><label className="prod-upload">{photo ? <img src={photo.url} alt="Uploaded question preview" /> : <Upload size={26} />}<strong>{photo ? photo.file.name : 'Drop an image here or browse'}</strong><span>{photo ? `${(photo.file.size / 1024).toFixed(0)} KB · ${photo.file.type}` : 'JPG, PNG or WEBP · up to 10 MB'}</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e => { setAnalysis(null); onPhoto(e.target.files?.[0]) }} /></label>{photo && <><label className="photo-question-label">Question text or what you want explained<textarea value={questionText} onChange={e => setQuestionText(e.target.value)} placeholder="Type the question, options or your doubt here…" rows={4} /></label><div className="prod-photo-actions"><button className="button primary" onClick={() => void runAnalysis()} disabled={busy}>{busy ? 'Preparing solution…' : 'Analyze with context'} <ArrowRight size={15} /></button><button className="button ghost" onClick={() => { setAnalysis(null); setQuestionText(''); onRemove() }}><X size={15} /> Remove</button></div></>}{analysis && <div className="prod-analysis"><ShieldCheck size={18} /><div><strong>{analysis.reply}</strong><p>{analysis.notice}</p><button className="text-action" onClick={() => window.dispatchEvent(new CustomEvent('prep-notice', { detail: 'Photo context is ready for the tutor.' }))}>Continue in tutor <ArrowRight size={14} /></button></div></div>}<div className="prod-photo-checklist"><strong>Better results</strong><span>• Keep the full question and options visible</span><span>• Add the chapter or your attempted step</span><span>• Verify final facts against approved NCERT material</span></div></section>
}
